function schedule(){const profiles=new Map(data.profiles.map(p=>[p.handle,p]));scheduled=data.posts.map(p=>({...p,replay_at:dueAt(p,profiles.get(p.profile_handle),data.state.clock)})).sort((a,b)=>b.replay_at-a.replay_at||b.created_at.localeCompare(a.created_at)||b.key.localeCompare(a.key));updateReleased();armReleaseTimer();}
