function nav(){for(const id of ['desktop-nav','mobile-nav']){const root=$(id);if(!root.children.length)for(const name of ['home','profiles','likes','search','settings']){const b=button('','',()=>navigate(name));b.dataset.view=name;b.setAttribute('aria-label',({home:'Home',profiles:'Posters',likes:'Favs',search:'Search',settings:'Settings'})[name]);const glyph=e('span','nav-icon');glyph.append(createNavIcon(name));glyph.dataset.selected='false';b.append(glyph,e('span','',({home:'Home',profiles:'Posters',likes:'Favs',search:'Search',settings:'Settings'})[name]));root.append(b);}for(const b of root.children){const active=view===b.dataset.view||(view==='profile'&&b.dataset.view==='profiles');const glyph=b.querySelector('.nav-icon');if(glyph.dataset.selected!==String(active)){glyph.replaceChildren(createNavIcon(b.dataset.view,active));glyph.dataset.selected=String(active);}b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');}}}
let sidebarKey='';
function recentPosterOrder(profiles,posts,now=Date.now()){const counts=new Map(),cutoff=now-7*86400000;for(const post of posts)if(post.replay_at>cutoff&&post.replay_at<=now)counts.set(post.profile_handle,(counts.get(post.profile_handle)||0)+1);return [...profiles].sort((a,b)=>(counts.get(b.handle)||0)-(counts.get(a.handle)||0)||a.handle.localeCompare(b.handle));}
