function filtered(){let posts=released;if(view==='likes'){const likedKeys=new Set(data.state.bookmarks),past=available(data.posts.filter(p=>likedKeys.has(p.key)),data.profiles,data.state.clock?{...data.state.clock,restarts:undefined}:null,Date.now());const current=new Map(past.map(p=>[p.key,p]));for(const p of released)current.set(p.key,p);posts=filterMuted([...current.values()],data.state.muted_terms||[]).filter(p=>data.state.bookmarks.includes(p.key)).sort((a,b)=>b.replay_at-a.replay_at);}if(view==='profile'){posts=posts.filter(p=>p.profile_handle===selectedProfile);if(profileMedia!=='posts')posts=posts.filter(p=>[...p.media,...(p.quoted_post?.media||[])].some(m=>m.type===(profileMedia==='photos'?'photo':'video')));}if(view==='search'){const q=query.toLocaleLowerCase().trim();if(q)posts=posts.filter(p=>[p.text,p.author.handle,p.author.display_name,p.profile_handle,p.quoted_post?.text||''].some(t=>t.toLocaleLowerCase().includes(q)));if(savedOnly)posts=posts.filter(p=>data.state.bookmarks.includes(p.key));}return posts;}
