function decorateCatchup(rows){const posts=filtered(),boundary=view==='home'?unreadBoundary(posts,visitSeenAt):null,boundaryKey=boundary?posts[boundary.index]?.key:null;for(const row of rows){row.classList.toggle('catchup-boundary',row.dataset.key===boundaryKey);if(row.dataset.key===boundaryKey)row.setAttribute('data-catchup','You’re caught up · older tweets below');else row.removeAttribute('data-catchup');}}
